using System.Net;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly FakeProvider provider = new();
    private readonly HttpClient client;

    public HttpPaymentGatewayTests()
    {
        client = new HttpClient { BaseAddress = new Uri(provider.BaseUrl) };
    }

    [Fact]
    public async Task Sends_a_json_post_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        provider.Respond(200, """{"status":"approved"}""");

        await new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);

        var received = Assert.Single(provider.Requests);
        Assert.Equal("POST", received.Method);
        Assert.Equal("/v1/authorizations", received.Path);
        Assert.StartsWith("application/json", received.ContentType);
        using var json = JsonDocument.Parse(received.Body);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        provider.Respond(200, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        provider.Respond(200, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        provider.Respond(200, """{"id":"auth_1","status":"approved","risk":{"score":3}}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task An_unknown_status_is_never_treated_as_approved()
    {
        provider.Respond(200, """{"status":"pending"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task An_answer_without_a_status_is_never_treated_as_approved()
    {
        provider.Respond(200, """{"decision":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_refused_payment_402_is_declined_even_when_the_body_says_approved()
    {
        provider.Respond(402, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_refused_payment_402_with_an_error_body_is_declined()
    {
        provider.Respond(402, """{"error":"card_refused"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_error_statuses_surface_as_failures_not_as_decisions(int status)
    {
        provider.Respond(status, """{"status":"approved"}""");

        await Assert.ThrowsAsync<HttpRequestException>(Authorize);
    }

    [Fact]
    public async Task A_malformed_body_surfaces_as_a_failure()
    {
        provider.Respond(200, "not json");

        await Assert.ThrowsAsync<JsonException>(Authorize);
    }

    private Task<AuthorizationOutcome> Authorize() =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-1", new Money(10m, "USD"), CancellationToken.None);

    public void Dispose()
    {
        client.Dispose();
        provider.Dispose();
    }

    private sealed record ReceivedRequest(string Method, string Path, string? ContentType, string Body);

    private sealed class FakeProvider : IDisposable
    {
        private readonly HttpListener listener = new();
        private readonly CancellationTokenSource stop = new();
        private readonly Task loop;
        private int status = 200;
        private string body = "{}";

        public FakeProvider()
        {
            // Reserve a free port, then release it for the listener.
            var probe = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
            probe.Start();
            var port = ((IPEndPoint)probe.LocalEndpoint).Port;
            probe.Stop();
            BaseUrl = $"http://127.0.0.1:{port}/";
            listener.Prefixes.Add(BaseUrl);
            listener.Start();
            loop = Task.Run(Serve);
        }

        public string BaseUrl { get; }

        public List<ReceivedRequest> Requests { get; } = [];

        public void Respond(int statusCode, string responseBody)
        {
            status = statusCode;
            body = responseBody;
        }

        private async Task Serve()
        {
            while (!stop.IsCancellationRequested)
            {
                HttpListenerContext context;
                try { context = await listener.GetContextAsync(); }
                catch (Exception) { return; }

                using var reader = new StreamReader(context.Request.InputStream);
                var requestBody = await reader.ReadToEndAsync();
                lock (Requests)
                {
                    Requests.Add(new ReceivedRequest(context.Request.HttpMethod, context.Request.Url!.AbsolutePath,
                        context.Request.ContentType, requestBody));
                }

                var bytes = System.Text.Encoding.UTF8.GetBytes(body);
                context.Response.StatusCode = status;
                context.Response.ContentType = "application/json";
                context.Response.ContentLength64 = bytes.Length;
                await context.Response.OutputStream.WriteAsync(bytes);
                context.Response.Close();
            }
        }

        public void Dispose()
        {
            stop.Cancel();
            listener.Close();
            loop.Wait(TimeSpan.FromSeconds(5));
            stop.Dispose();
        }
    }
}
